const lockReplayReserveAuthorityPool = `-- name: LockReplayReserveAuthorityPool :many
SELECT authority_version.assignment_id,
    authority_version.task_id,
    authority_version.task_version,
    authority_version.created_at
FROM replay_reserve_authority_pool_versions AS authority_version
WHERE authority_version.assignment_id = $1
ORDER BY authority_version.task_id, authority_version.task_version
FOR UPDATE
`

func (q *Queries) LockReplayReserveAuthorityPool(ctx context.Context, assignmentID uuid.UUID) ([]ReplayReserveAuthorityPoolVersion, error) {
	rows, err := q.db.Query(ctx, lockReplayReserveAuthorityPool, assignmentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReplayReserveAuthorityPoolVersion{}
	for rows.Next() {
		var i ReplayReserveAuthorityPoolVersion
		if err := rows.Scan(
			&i.AssignmentID,
			&i.TaskID,
			&i.TaskVersion,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

